class Solution {
  public int maxValue(int[] nums, int k) {
    int n = nums.length, all = 0;
    for (int x : nums) all |= x;
    boolean[][][] left = new boolean[n + 1][k + 1][all + 1];
    boolean[][][] right = new boolean[n + 1][k + 1][all + 1];
    left[0][0][0] = true;
    for (int i = 0; i < n; i++) {
      for (int used = 0; used <= k; used++)
        for (int mask = 0; mask <= all; mask++)
          if (left[i][used][mask]) {
            left[i + 1][used][mask] = true;
            if (used < k) left[i + 1][used + 1][mask | nums[i]] = true;
          }
    }
    right[n][0][0] = true;
    for (int i = n - 1; i >= 0; i--) {
      for (int used = 0; used <= k; used++)
        for (int mask = 0; mask <= all; mask++)
          if (right[i + 1][used][mask]) {
            right[i][used][mask] = true;
            if (used < k) right[i][used + 1][mask | nums[i]] = true;
          }
    }
    int answer = 0;
    for (int split = k; split <= n - k; split++)
      for (int a = 0; a <= all; a++)
        if (left[split][k][a])
          for (int b = 0; b <= all; b++) if (right[split][k][b]) answer = Math.max(answer, a ^ b);
    return answer;
  }
}
